<?php
session_start();
if(($_SESSION['logged_in']??false)!==true){http_response_code(401);exit('Please log in.');}
header('Cache-Control: no-store');
if(empty($_SESSION['chat_csrf']))$_SESSION['chat_csrf']=bin2hex(random_bytes(24));
function db():PDO{$p=parse_url(getenv('DATABASE_URL')?:'');if(!$p||empty($p['host'])||empty($p['user'])||empty($p['path']))throw new RuntimeException('Database is not configured');return new PDO('pgsql:host='.$p['host'].';port='.($p['port']??5432).';dbname='.ltrim($p['path'],'/'),urldecode($p['user']),urldecode($p['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
function setup(PDO $d):void{$d->exec("CREATE TABLE IF NOT EXISTS app_chat_users (id BIGSERIAL PRIMARY KEY, identity_key VARCHAR(255) UNIQUE NOT NULL, display_name VARCHAR(150) NOT NULL, last_seen TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS app_chat_messages(id BIGSERIAL PRIMARY KEY,sender_id BIGINT NOT NULL REFERENCES app_chat_users(id),recipient_id BIGINT NOT NULL REFERENCES app_chat_users(id),body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),read_at TIMESTAMPTZ); CREATE INDEX IF NOT EXISTS chat_msg_pair ON app_chat_messages(sender_id,recipient_id,id); CREATE TABLE IF NOT EXISTS app_chat_calls(id BIGSERIAL PRIMARY KEY,caller_id BIGINT NOT NULL REFERENCES app_chat_users(id),callee_id BIGINT NOT NULL REFERENCES app_chat_users(id),kind VARCHAR(10) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ringing',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS app_chat_signals(id BIGSERIAL PRIMARY KEY,call_id BIGINT NOT NULL REFERENCES app_chat_calls(id) ON DELETE CASCADE,sender_id BIGINT NOT NULL REFERENCES app_chat_users(id),payload JSONB NOT NULL,created_at TIMESTAMPTZ DEFAULT now());");}
function ensureDelivery(PDO $d):void{$d->exec("ALTER TABLE app_chat_messages ADD COLUMN IF NOT EXISTS delivered_at TIMESTAMPTZ");}
function reply($data,int $status=200):never{header('Content-Type: application/json');http_response_code($status);echo json_encode($data,JSON_UNESCAPED_SLASHES);exit;}
try{
$d=db();setup($d);ensureDelivery($d);
// Login implementation must supply a stable, unique authenticated account ID.
$identity=$_SESSION['user_id']??$_SESSION['id']??null;
if($identity===null||!is_scalar($identity)||trim((string)$identity)==='')throw new RuntimeException('Chat requires a stable authenticated user ID in the login session (user_id or id).');
$key='account:'.(string)$identity;
// The login.php users table is the authoritative contact directory.
// Register every account, even if the person has never opened Messages.
// Keep chat IDs stable: existing conversations and calls remain attached to the same IDs.
$d->exec("INSERT INTO app_chat_users(identity_key,display_name,last_seen)
 SELECT 'account:' || id::text,
        initcap(split_part(username,'@',1)),
        NULL
 FROM users
 WHERE TRUE
 ON CONFLICT(identity_key) DO UPDATE
 SET display_name=EXCLUDED.display_name");
$q=$d->prepare('UPDATE app_chat_users SET last_seen=now() WHERE identity_key=? RETURNING id');
$q->execute([$key]);$me=(int)$q->fetchColumn();
if(!$me)throw new RuntimeException('Authenticated account not found in the users directory.');
// Allow message polling and sending in separate requests without a PHP session lock.
$chatCsrf=$_SESSION['chat_csrf'];
session_write_close();
$action=$_GET['action']??'';
if($action){
 if($_SERVER['REQUEST_METHOD']==='POST' && !hash_equals($chatCsrf,(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'')))reply(['error'=>'Security token invalid'],403);
 $input=json_decode(file_get_contents('php://input'),true)??[];$other=(int)($input['user']??$_GET['user']??0);
 $check=function(int $id)use($d,$me){if($id<1||$id===$me)return false;$s=$d->prepare('SELECT 1 FROM app_chat_users WHERE id=?');$s->execute([$id]);return(bool)$s->fetchColumn();};
 if($action==='users'){
 // Delivery means the recipient's authenticated Messages client has checked its inbox.
 $d->prepare('UPDATE app_chat_messages SET delivered_at=now() WHERE recipient_id=? AND delivered_at IS NULL')->execute([$me]);
 $s=$d->prepare('SELECT u.id,u.display_name,u.last_seen,(SELECT count(*) FROM app_chat_messages m WHERE m.sender_id=u.id AND m.recipient_id=? AND m.read_at IS NULL) AS unread, (SELECT m.body FROM app_chat_messages m WHERE (m.sender_id=u.id AND m.recipient_id=?) OR (m.sender_id=? AND m.recipient_id=u.id) ORDER BY m.id DESC LIMIT 1) AS last_body, (SELECT m.created_at FROM app_chat_messages m WHERE (m.sender_id=u.id AND m.recipient_id=?) OR (m.sender_id=? AND m.recipient_id=u.id) ORDER BY m.id DESC LIMIT 1) AS last_message_at FROM app_chat_users u WHERE u.id<>? ORDER BY last_message_at DESC NULLS LAST,u.display_name,u.id');
 $s->execute([$me,$me,$me,$me,$me,$me]);reply(['me'=>$me,'users'=>$s->fetchAll()]);} 
 if($action==='messages'&&$check($other)){$s=$d->prepare('SELECT id,sender_id,recipient_id,body,created_at,read_at,delivered_at FROM (SELECT * FROM app_chat_messages WHERE (sender_id=? AND recipient_id=?) OR (sender_id=? AND recipient_id=?) ORDER BY id DESC LIMIT 150) x ORDER BY id');$s->execute([$me,$other,$other,$me]);$d->prepare('UPDATE app_chat_messages SET read_at=now(),delivered_at=COALESCE(delivered_at,now()) WHERE sender_id=? AND recipient_id=? AND read_at IS NULL')->execute([$other,$me]);reply(['messages'=>$s->fetchAll()]);}
 if($action==='send'&&$check($other)){$body=trim((string)($input['body']??''));if($body===''||mb_strlen($body)>4000)reply(['error'=>'Message must be 1–4000 characters'],422);$s=$d->prepare('INSERT INTO app_chat_messages(sender_id,recipient_id,body) VALUES (?,?,?) RETURNING id');$s->execute([$me,$other,$body]);reply(['ok'=>true,'id'=>$s->fetchColumn()]);}
 if($action==='call'&&$check($other)){$kind=$input['kind']??'';if(!in_array($kind,['audio','video'],true))reply(['error'=>'Invalid call type'],422);$s=$d->prepare("INSERT INTO app_chat_calls(caller_id,callee_id,kind) VALUES (?,?,?) RETURNING id");$s->execute([$me,$other,$kind]);reply(['id'=>(int)$s->fetchColumn()]);}
 if($action==='calls'){$s=$d->prepare("SELECT c.*,u.display_name AS caller_name FROM app_chat_calls c JOIN app_chat_users u ON u.id=c.caller_id WHERE (callee_id=? OR caller_id=?) AND status IN ('ringing','active') AND created_at>now()-interval '2 hours' ORDER BY id DESC LIMIT 10");$s->execute([$me,$me]);reply(['calls'=>$s->fetchAll()]);}
 $call=(int)($input['call']??$_GET['call']??0);
 if(in_array($action,['signal','signals','status'],true)){$s=$d->prepare('SELECT * FROM app_chat_calls WHERE id=? AND (caller_id=? OR callee_id=?)');$s->execute([$call,$me,$me]);$c=$s->fetch();if(!$c)reply(['error'=>'Call not found'],404);
 if($action==='status'){$status=$input['status']??'';if(!in_array($status,['active','ended','declined'],true))reply(['error'=>'Invalid status'],422);if($status==='active'&&(int)$c['callee_id']!==$me)reply(['error'=>'Only recipient may answer'],403);$d->prepare('UPDATE app_chat_calls SET status=?,updated_at=now() WHERE id=?')->execute([$status,$call]);reply(['ok'=>true]);}
 if($action==='signal'){$payload=$input['payload']??null;if(!is_array($payload)||strlen(json_encode($payload))>20000||!in_array($payload['type']??'',['offer','answer','candidate'],true))reply(['error'=>'Invalid signal'],422);$d->prepare('INSERT INTO app_chat_signals(call_id,sender_id,payload) VALUES (?,?,?)')->execute([$call,$me,json_encode($payload)]);reply(['ok'=>true]);}
 $after=max(0,(int)($_GET['after']??0));$s=$d->prepare('SELECT id,payload FROM app_chat_signals WHERE call_id=? AND sender_id<>? AND id>? ORDER BY id LIMIT 100');$s->execute([$call,$me,$after]);$rows=$s->fetchAll();foreach($rows as &$r)$r['payload']=json_decode($r['payload'],true);reply(['signals'=>$rows,'status'=>$c['status']]);}
 reply(['error'=>'Invalid request'],400);
}
}catch(Throwable $e){error_log('Messages: '.$e->getMessage());if(isset($_GET['action']))reply(['error'=>$e->getMessage()==='Chat requires a stable authenticated user ID in the login session (user_id or id).'?$e->getMessage():'Messaging service unavailable'],503);$startupError='Messaging setup needs attention. Check login user ID and PostgreSQL configuration.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages & Calls</title><style>
*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden}body{font:14px system-ui,Arial;background:#f6f4f2;color:#2d2522}.app{display:grid;grid-template-columns:minmax(245px,320px) minmax(0,1fr);height:100%;height:100dvh;min-height:0;overflow:hidden}.side{background:white;border-right:1px solid #e9e3df;display:flex;flex-direction:column;min-height:0;min-width:0}.side-top{flex:none;background:#fff;z-index:1;border-bottom:1px solid #eee7e2;padding:18px 16px 12px}.brand{font-size:21px;font-weight:800;color:#422a22}.sub{font-size:12px;color:#95867e;margin:3px 0 12px}.search{padding:11px 13px;border:1px solid #e6ddd7;border-radius:12px;width:100%;outline:none}.search:focus{border-color:#795548}.users{overflow-y:auto;overscroll-behavior:contain;min-height:0;flex:1;scrollbar-width:thin}.user{display:flex;align-items:center;gap:11px;padding:13px 15px;cursor:pointer;border:0;border-bottom:1px solid #f3efec;background:transparent;width:100%;text-align:left;min-width:0}.user:hover,.user.selected{background:#f3eae5}.avatar{background:#eadad1;color:#5d4037;border-radius:50%;width:43px;height:43px;display:grid;place-items:center;font-weight:800;flex-shrink:0}.user-info{flex:1;min-width:0}.user-line{display:flex;gap:5px;align-items:center;justify-content:space-between}.uname{font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.hint{font-size:12px;color:#9a8d86;margin-top:4px}.preview{font-size:12px;color:#978b84;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:5px}.stamp{font-size:10px;color:#9a8d86;flex-shrink:0}.count{border-radius:20px;background:#6d4c41;color:white;padding:2px 7px;font-size:11px;flex-shrink:0}.main{display:flex;flex-direction:column;min-width:0;min-height:0;overflow:hidden}.head{background:white;padding:13px 20px;border-bottom:1px solid #e9e3df;display:flex;align-items:center;gap:11px;flex-shrink:0;min-height:72px}.head strong{font-size:16px}.actions{margin-left:auto;display:flex;gap:8px}button{font:inherit}button.action{border:1px solid #e8ded8;background:#fff;border-radius:11px;padding:10px;cursor:pointer;color:#5d4037}button.action:hover{background:#f6efeb}.back{display:none;border:0;background:none;font-size:22px;color:#5d4037;cursor:pointer}.messages{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:22px;display:flex;flex-direction:column;gap:11px;scrollbar-width:thin;background:#f7f3ef}.bubble{max-width:min(78%,560px);background:white;padding:11px 14px;border-radius:16px 16px 16px 4px;box-shadow:0 2px 9px #00000008;white-space:pre-wrap;overflow-wrap:anywhere;align-self:flex-start}.bubble.mine{align-self:flex-end;background:#e5d3c8;border-radius:16px 16px 4px 16px}.meta{display:flex;align-items:center;justify-content:flex-end;gap:5px;font-size:10px;color:#7e7068;margin-top:5px;white-space:nowrap}.ticks{font-size:15px;letter-spacing:-4px;padding-right:4px;color:#8b817a;font-weight:700}.ticks.read{color:#238ac5}.empty{margin:auto;text-align:center;color:#96857b;line-height:1.8}.empty b{font-size:20px;color:#60483d}.compose{flex:none;padding:12px 15px;background:#fff;border-top:1px solid #e9e3df;display:flex;gap:10px;align-items:center}.compose textarea{resize:none;flex:1;min-width:0;border:1px solid #e7ddd7;border-radius:12px;padding:11px 12px;font:inherit;height:46px;max-height:120px}.send{background:#5d4037;color:white;border:0;border-radius:12px;padding:0 20px;height:46px;cursor:pointer}.send:disabled{opacity:.45;cursor:default}.notice{padding:9px 18px;background:#fff3e6;color:#8c4e1d;display:none;flex:none}.callbox{position:fixed;inset:0;background:#161312ee;z-index:10;display:none;flex-direction:column;align-items:center;justify-content:center;color:white;gap:15px}.videos{display:flex;gap:12px;width:min(900px,94vw);height:min(55vh,500px)}video{background:#27211f;border-radius:16px;width:50%;object-fit:cover}.callbox button{border:0;border-radius:25px;padding:12px 23px;cursor:pointer}.hang{background:#d74646;color:white}.accept{background:#4c956c;color:white}.callcontrols{display:flex;gap:12px}
@media(max-width:700px){.app{display:block;position:relative}.side,.main{position:absolute;inset:0;width:100%;height:100%;transition:transform .22s ease}.side{transform:translateX(0)}.main{transform:translateX(100%)}.app.chat-open .side{transform:translateX(-25%);pointer-events:none}.app.chat-open .main{transform:translateX(0)}.back{display:inline-block}.head{padding:10px 12px}.head strong{font-size:15px}.actions{gap:4px}.actions .action{font-size:12px;padding:8px}.messages{padding:13px}.bubble{max-width:89%}.compose{padding:9px}.send{padding:0 13px}.videos{flex-direction:column}.videos video{width:100%;height:50%}}
@media(max-width:370px){.head .avatar{display:none}.actions .action{font-size:11px;padding:7px}}
</style></head><body><div class="app" id="app"><aside class="side"><div class="side-top"><div class="brand">💬 Messages</div><div class="sub">Connect with your team</div><input class="search" id="search" placeholder="Search colleagues…" aria-label="Search colleagues"></div><div class="users" id="users"></div></aside><main class="main"><header class="head"><button class="back" id="back" aria-label="Back to contacts">‹</button><span class="avatar" id="headAvatar">✦</span><div style="min-width:0"><strong id="headName">Team conversations</strong><div class="hint" id="headStatus">Select a contact to chat</div></div><div class="actions"><button class="action" id="audio" title="Audio call" disabled>☎ Audio</button><button class="action" id="video" title="Video call" disabled>▣ Video</button></div></header><div class="notice" id="notice"<?=isset($startupError)?' style="display:block"':''?>><?=isset($startupError)?htmlspecialchars($startupError,ENT_QUOTES,'UTF-8'):''?></div><div class="messages" id="messages"><div class="empty"><b>Start a conversation</b><div>Select a colleague from the contact list to view messages.</div></div></div><form class="compose" id="compose"><textarea id="body" placeholder="Write a message…" aria-label="Message" disabled></textarea><button class="send" id="send" disabled>Send ➤</button></form></main></div><div class="callbox" id="callbox"><h2 id="calltitle">Calling…</h2><div class="videos"><video id="remote" autoplay playsinline></video><video id="local" autoplay muted playsinline></video></div><div class="callcontrols"><button class="accept" id="accept" style="display:none">Answer</button><button id="mute">Mute</button><button id="camera">Camera off</button><button class="hang" id="hang">End call</button></div></div><script>
const csrf=<?=json_encode($chatCsrf??'')?>;let me=<?=json_encode($me??null)?>,selected=null,users=[],lastMessages='',currentCall=null,pc=null,stream=null,lastSignal=0,pendingCandidates=[],answering=false,renderedContacts='',messageBusy=false;
const $=id=>document.getElementById(id);const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(action,data=null,params=''){const r=await fetch('messages.php?action='+action+params,{method:data?'POST':'GET',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data?JSON.stringify(data):undefined,cache:'no-store'});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
function notify(s){$('notice').textContent=s;$('notice').style.display='block';setTimeout(()=>$('notice').style.display='none',5500)}
function clock(s){if(!s)return '';const d=new Date(s);return isNaN(d)?'':d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}
function renderUsers(){const term=$('search').value.toLowerCase();const html=users.filter(u=>u.display_name.toLowerCase().includes(term)).map(u=>`<button class="user ${selected===+u.id?'selected':''}" data-id="${u.id}"><span class="avatar">${escapeHTML(u.display_name[0]?.toUpperCase()||'?')}</span><span class="user-info"><span class="user-line"><span class="uname">${escapeHTML(u.display_name)}</span><span class="stamp">${clock(u.last_message_at)}</span></span><div class="preview">${escapeHTML(u.last_body||'Start a conversation')}</div></span>${+u.unread?`<span class="count">${u.unread}</span>`:''}</button>`).join('')||'<div class="hint" style="padding:20px">No matching contacts</div>';if(html!==renderedContacts){const scroll=$('users').scrollTop;$('users').innerHTML=html;$('users').scrollTop=scroll;renderedContacts=html;}}
async function refreshUsers(){try{const d=await api('users');if(!Array.isArray(d.users))throw Error('Invalid contact directory response');users=d.users;renderUsers()}catch(e){$('users').innerHTML='<div class="hint" style="padding:20px;line-height:1.6">Unable to load contacts. '+escapeHTML(e.message)+'<br><button type="button" id="retryContacts">Retry</button></div>';$('retryContacts').onclick=refreshUsers;renderedContacts='';notify(e.message)}}
function selectUser(id){selected=id;const u=users.find(x=>+x.id===id);$('headName').textContent=u?.display_name||'Colleague';$('headAvatar').textContent=(u?.display_name||'?')[0].toUpperCase();$('headStatus').textContent='Private conversation';['audio','video','body','send'].forEach(k=>$(k).disabled=false);lastMessages='';$('messages').innerHTML='<div class="empty">Loading conversation…</div>';$('app').classList.add('chat-open');renderUsers();refreshMessages()}
async function refreshMessages(){if(!selected||messageBusy)return;const recipient=selected;messageBusy=true;try{const d=await api('messages',null,'&user='+recipient);if(selected!==recipient)return;const key=JSON.stringify(d.messages);if(key===lastMessages)return;lastMessages=key;const el=$('messages'),atBottom=el.scrollHeight-el.scrollTop-el.clientHeight<110;el.innerHTML=d.messages.length?d.messages.map(m=>{const mine=+m.sender_id===+me;const status=mine?(m.read_at?'<span class="ticks read" title="Read">✓✓</span>':m.delivered_at?'<span class="ticks" title="Delivered">✓✓</span>':'<span class="ticks" title="Sent">✓</span>'):'';return `<div class="bubble ${mine?'mine':''}">${escapeHTML(m.body)}<div class="meta"><span>${clock(m.created_at)}</span>${status}</div></div>`}).join(''):'<div class="empty">No messages yet. Say hello 👋</div>';if(atBottom||d.messages.length<4)el.scrollTop=el.scrollHeight;}catch(e){notify(e.message)}finally{messageBusy=false}}
$('users').onclick=e=>{const b=e.target.closest('button[data-id]');if(b)selectUser(+b.dataset.id)};$('search').oninput=renderUsers;$('back').onclick=()=>{$('app').classList.remove('chat-open')};
$('compose').onsubmit=async e=>{e.preventDefault();const body=$('body').value.trim(),recipient=selected;if(!body||!recipient)return;try{$('send').disabled=true;await api('send',{user:recipient,body});if(selected===recipient){$('body').value='';await refreshMessages()}await refreshUsers()}catch(e){notify(e.message)}finally{$('send').disabled=!selected}};$('body').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('compose').requestSubmit()}};
async function media(kind){stream=await navigator.mediaDevices.getUserMedia({audio:true,video:kind==='video'});$('local').srcObject=stream;$('local').style.display=kind==='video'?'block':'none';$('camera').style.display=kind==='video'?'':'none';pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});stream.getTracks().forEach(t=>pc.addTrack(t,stream));pc.ontrack=e=>$('remote').srcObject=e.streams[0];pc.onicecandidate=e=>{if(e.candidate&&currentCall)api('signal',{call:currentCall.id,payload:{type:'candidate',candidate:e.candidate}}).catch(console.error)};$('callbox').style.display='flex'}
async function startCall(kind){if(!selected||currentCall)return;try{const c=await api('call',{user:selected,kind});currentCall={id:c.id,kind,caller_id:me,callee_id:selected,status:'ringing'};lastSignal=0;$('calltitle').textContent='Calling…';$('accept').style.display='none';await media(kind);const offer=await pc.createOffer();await pc.setLocalDescription(offer);await api('signal',{call:c.id,payload:{type:'offer',sdp:offer}})}catch(e){notify(e.message);await endCall()}}
async function acceptCall(){if(!currentCall)return;try{answering=true;await media(currentCall.kind);await api('status',{call:currentCall.id,status:'active'});$('accept').style.display='none';$('calltitle').textContent='Connected';await pollSignals()}catch(e){notify(e.message);await endCall()}}
async function endCall(){const id=currentCall?.id;currentCall=null;answering=false;lastSignal=0;pendingCandidates=[];if(pc){pc.close();pc=null}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}$('remote').srcObject=null;$('local').srcObject=null;$('callbox').style.display='none';$('accept').style.display='none';if(id)try{await api('status',{call:id,status:'ended'})}catch(e){}}
async function pollSignals(){if(!currentCall)return;const d=await api('signals',null,'&call='+currentCall.id+'&after='+lastSignal);if(['ended','declined'].includes(d.status)){await endCall();return}for(const s of d.signals){lastSignal=Math.max(lastSignal,+s.id);const p=s.payload;if(p.type==='offer'&&pc){await pc.setRemoteDescription(p.sdp);const ans=await pc.createAnswer();await pc.setLocalDescription(ans);await api('signal',{call:currentCall.id,payload:{type:'answer',sdp:ans}})}else if(p.type==='answer'&&pc&&!pc.currentRemoteDescription){await pc.setRemoteDescription(p.sdp)}else if(p.type==='candidate'){if(pc?.remoteDescription)await pc.addIceCandidate(p.candidate);else pendingCandidates.push(p.candidate)}}if(pc?.remoteDescription){for(const c of pendingCandidates.splice(0))await pc.addIceCandidate(c)}}
async function refreshCalls(){try{if(!currentCall){const d=await api('calls');const incoming=d.calls.find(c=>+c.callee_id===me&&c.status==='ringing');if(incoming){currentCall=incoming;lastSignal=0;$('callbox').style.display='flex';$('calltitle').textContent=(incoming.caller_name||'Colleague')+' is calling ('+incoming.kind+')';$('accept').style.display='';$('local').style.display='none';$('camera').style.display='none';}}else if(pc)await pollSignals();else{const d=await api('calls');if(!d.calls.some(c=>+c.id===+currentCall.id))await endCall();}}catch(e){console.warn(e)}}
$('audio').onclick=()=>startCall('audio');$('video').onclick=()=>startCall('video');$('accept').onclick=acceptCall;$('hang').onclick=endCall;$('mute').onclick=()=>{if(!stream)return;const t=stream.getAudioTracks()[0];if(t){t.enabled=!t.enabled;$('mute').textContent=t.enabled?'Mute':'Unmute'}};$('camera').onclick=()=>{const t=stream?.getVideoTracks()[0];if(t){t.enabled=!t.enabled;$('camera').textContent=t.enabled?'Camera off':'Camera on'}};
refreshUsers();setInterval(()=>{if(!document.hidden){refreshUsers();refreshMessages();refreshCalls()}},2500);refreshCalls();
</script></body></html>
